"civicsmith.css": Object.freeze({ type: "text/css", body: "/* ============================================================
   Civicsmith · the visual language (design phase step 4, DEC-138)
   GENERATED by build.py from palette.json (colors) + tokens.head.css + components.css.
   Edit those, never this file. One system for every member screen and the published case,
   replacing civicos-ui/tokens.css, the action-design sketches' look and the measures map's
   placeholders. Faces: faces.css (shipped inside the group's copy, principle 9.6).

   The system's rules:
   1. Color always means something. Verdigris (the patina on a brass plumb bob) is the one
      color for acting and for Civicsmith itself; rust is attention only (a clock, a change,
      a refusal, something visible outside the group); each evidence scale has its own hue;
      machine work and another group's work carry no hue and are told apart by edge, mark
      and word.
   2. Three voices in type: serif for words people wrote (the group's questions, findings and
      cases; passages quoted from documents), sans for Civicsmith's own words, mono only for
      identifiers machines check (fingerprints, short names, receipt numbers).
   3. Rules before shadows; corners nearly square, like a printed form; no pill shapes.
   4. Nothing moves unless the member needs to act (principle 7.2).
   5. Every color has a word or an icon beside it (principle 8.2); WCAG 2.2 AA in both themes
      (check_contrast.py).
   ============================================================ */

:root {
  --c-ground: #EDEFE9;
  --c-ground-2: #E3E7DF;
  --c-surface: #F8F9F5;
  --c-sheet: #FDFDFB;
  --c-ink: #15222C;
  --c-ink-2: #334149;
  --c-muted: #55635E;
  --c-rule: #C3C9BE;
  --c-rule-strong: #7E877C;
  --c-accent: #2B6A5D;
  --c-accent-strong: #1D4E44;
  --c-accent-tint: #E2EEE9;
  --c-on-accent: #FFFFFF;
  --c-signal: #A23B19;
  --c-signal-tint: #F7E9E2;
  --c-capture: #1F5C9E;
  --c-capture-tint: #E3ECF7;
  --c-connection: #8A2F6E;
  --c-connection-tint: #F4E4EF;
  --c-testimony: #865300;
  --c-testimony-tint: #F7ECD9;
  --c-subject: #55621A;
  --c-subject-tint: #EDF0DC;
  --c-stage: #3A587F;
  --c-ready: #2E6E4A;
  --c-ident: #9B3355;
  --c-machine: #4A5560;
  --c-machine-tint: #ECEEF0;
  --c-elsewhere: #4B4F7A;
  --c-elsewhere-tint: #E8E9F2;
  --c-focus: #1D4E44;
  --c-kind-money: #773AC1;
  --c-kind-part: #0092C3;
  --c-kind-mention: #DF407F;
  color-scheme: light;

  /* type: the three voices */
  --f-serif: "Civicsmith Serif", "Source Serif 4", Georgia, "Times New Roman", serif;
  --f-sans: "Civicsmith Sans", "Source Sans 3", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --f-mono: "Civicsmith Mono", "Source Code Pro", ui-monospace, Menlo, Consolas, monospace;
  --t-xs: 0.8125rem;   /* 13px: labels, marks, eyebrows */
  --t-sm: 0.875rem;    /* 14px: secondary lines */
  --t-md: 1rem;        /* 16px: the working default; never smaller in a field */
  --t-lg: 1.125rem;    /* 18px: published body; a record's lines */
  --t-xl: 1.3125rem;   /* 21px: a record's title */
  --t-2xl: 1.625rem;   /* 26px: a page title */
  --t-3xl: 2.125rem;   /* 34px: the published case's title */
  --t-4xl: 2.75rem;    /* 44px: the published masthead, wide screens */
  --lh-tight: 1.2; --lh-ui: 1.45; --lh-read: 1.6;
  --track-caps: 0.07em;
  --measure: 68ch;

  /* space: a 4px base */
  --s-1: 4px; --s-2: 8px; --s-3: 12px; --s-4: 16px; --s-5: 24px; --s-6: 32px; --s-7: 48px; --s-8: 64px;

  /* shape */
  --r-0: 0; --r-1: 2px; --r-2: 4px;
  --hair: 1px solid var(--c-rule);
  --hair-strong: 1px solid var(--c-rule-strong);
  --shadow-float: 0 1px 2px rgb(10 20 25 / .10), 0 8px 24px rgb(10 20 25 / .14); /* the hold strip, a dialog, a menu; nothing else */

  /* motion: short, no bounce, only when the member must act */
  --d-1: 120ms; --d-2: 200ms; --ease: cubic-bezier(.2,0,.2,1);

  /* layout */
  --rail: 184px; --dock: 380px; --mast: 52px; --tap: 44px;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --c-ground: #11181C;
  --c-ground-2: #172026;
  --c-surface: #1A242A;
  --c-sheet: #1E2930;
  --c-ink: #E3E9E4;
  --c-ink-2: #C3CCC6;
  --c-muted: #9AA7A1;
  --c-rule: #33414A;
  --c-rule-strong: #73817A;
  --c-accent: #74C2AE;
  --c-accent-strong: #9AD8C7;
  --c-accent-tint: #1C332D;
  --c-on-accent: #0D1A16;
  --c-signal: #EE9874;
  --c-signal-tint: #3A231A;
  --c-capture: #8DB9EE;
  --c-capture-tint: #1B2B40;
  --c-connection: #E39BCB;
  --c-connection-tint: #36202F;
  --c-testimony: #E7B865;
  --c-testimony-tint: #352A15;
  --c-subject: #BACB6B;
  --c-subject-tint: #2A3016;
  --c-stage: #93B1DC;
  --c-ready: #7FCB9E;
  --c-ident: #EC93AE;
  --c-machine: #AEB8C2;
  --c-machine-tint: #232B32;
  --c-elsewhere: #AEB2E6;
  --c-elsewhere-tint: #24263B;
  --c-focus: #9AD8C7;
  --c-kind-money: #A473FF;
  --c-kind-part: #007BAA;
  --c-kind-mention: #D5305F;
  color-scheme: dark;
  --shadow-float: 0 1px 2px rgb(0 0 0 / .4), 0 8px 24px rgb(0 0 0 / .5);
} }
:root[data-theme="dark"], .cs[data-theme="dark"] {
  --c-ground: #11181C;
  --c-ground-2: #172026;
  --c-surface: #1A242A;
  --c-sheet: #1E2930;
  --c-ink: #E3E9E4;
  --c-ink-2: #C3CCC6;
  --c-muted: #9AA7A1;
  --c-rule: #33414A;
  --c-rule-strong: #73817A;
  --c-accent: #74C2AE;
  --c-accent-strong: #9AD8C7;
  --c-accent-tint: #1C332D;
  --c-on-accent: #0D1A16;
  --c-signal: #EE9874;
  --c-signal-tint: #3A231A;
  --c-capture: #8DB9EE;
  --c-capture-tint: #1B2B40;
  --c-connection: #E39BCB;
  --c-connection-tint: #36202F;
  --c-testimony: #E7B865;
  --c-testimony-tint: #352A15;
  --c-subject: #BACB6B;
  --c-subject-tint: #2A3016;
  --c-stage: #93B1DC;
  --c-ready: #7FCB9E;
  --c-ident: #EC93AE;
  --c-machine: #AEB8C2;
  --c-machine-tint: #232B32;
  --c-elsewhere: #AEB2E6;
